	} else if len(cfg.Args) != 1 {
		return cfg
	}
	if cfg.Args[packageIndex] != "@agentclientprotocol/codex-acp@latest" {
		return cfg
	}
	if path, err := exec.LookPath("codex-acp"); err == nil {
